[{'input': '#include <iostream>

using namespace std;

char *messages[] = {
    "\"You could not possibly
       have come at a better time,
       my dear Watson,\"",
    Q=#he said cordially.#,
    "\"I was afraid that you
       were 'engaged'.\"",
    Q=^"So I am. Very much so."^,
};

int main() {
    cout << "'The Adventures
      of Sherlock Holmes', by
      \"Sir Arthur Conan Doyle\"!\n";
    for (int i = 0; i < 8; i++)
        cout << messages[i] << endl;
    return 0;
}', 'output': '#include <iostream>

using namespace std;

char *messages[] = {
    '"You could not possibly
       have come at a better time,
       my dear Watson,"',
    "he said cordially.",
    Q=!"I was afraid that you
       were 'engaged'."!,
    '"So I am. Very much so."',
};

int main() {
    cout << Q=@'The Adventures
      of Sherlock Holmes', by
      "Sir Arthur Conan Doyle"!\n@;
    for (int i = 0; i < 8; i++)
        cout << messages[i] << endl;
    return 0;
}'}]

